static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    // Expect:
    // x: [B, Cin, W, H, D]
    // w: [Cout, Cin, kW, kH, kD]
    const gert::Shape* x_shape = context->GetInputShape(0);
    const gert::Shape* w_shape = context->GetInputShape(1);

    if (x_shape->GetOriginShape().GetDimNum() != 5 || w_shape->GetOriginShape().GetDimNum() != 5) {
        return ge::GRAPH_FAILED;
    }

    auto xOrigin = x_shape->GetOriginShape();
    auto wOrigin = w_shape->GetOriginShape();

    uint32_t B   = static_cast<uint32_t>(xOrigin.GetDim(0));
    uint32_t Cin = static_cast<uint32_t>(xOrigin.GetDim(1));
    uint32_t W   = static_cast<uint32_t>(xOrigin.GetDim(2));
    uint32_t H   = static_cast<uint32_t>(xOrigin.GetDim(3));
    uint32_t D   = static_cast<uint32_t>(xOrigin.GetDim(4));

    uint32_t Cout = static_cast<uint32_t>(wOrigin.GetDim(0));
    uint32_t kW   = static_cast<uint32_t>(wOrigin.GetDim(2));
    uint32_t kH   = static_cast<uint32_t>(wOrigin.GetDim(3));
    uint32_t kD   = static_cast<uint32_t>(wOrigin.GetDim(4));

    // Defaults: stride=1, padding=0, dilation=1
    if (Cin != static_cast<uint32_t>(wOrigin.GetDim(1))) {
        return ge::GRAPH_FAILED;
    }
    if (W < kW || H < kH || D < kD) {
        return ge::GRAPH_FAILED;
    }

    uint32_t Wo = W - kW + 1;
    uint32_t Ho = H - kH + 1;
    uint32_t Do = D - kD + 1;

    ConvStandard3dSquareInputAsymmetricKernelCustomTilingData tiling;
    tiling.set_B(B);
    tiling.set_Cin(Cin);
    tiling.set_Cout(Cout);
    tiling.set_W(W);
    tiling.set_H(H);
    tiling.set_D(D);
    tiling.set_kW(kW);
    tiling.set_kH(kH);
    tiling.set_kD(kD);
    tiling.set_Wo(Wo);
    tiling.set_Ho(Ho);
    tiling.set_Do(Do);

    context->SetBlockDim(8); // simple static blockDim

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    size_t *currentWorkspace = context->GetWorkspaceSizes(1);
    currentWorkspace[0] = 0;
    return ge::GRAPH_SUCCESS;
}
}

