    int64_t B = x.size(0);
    int64_t Cin = x.size(1);
    int64_t W = x.size(2);
    int64_t H = x.size(3);
    int64_t D = x.size(4);
    int64_t Cout = w.size(0);
    int64_t kW = w.size(2);
    int64_t kH = w.size(3);
    int64_t kD = w.size(4);
    TORCH_CHECK(Cin == w.size(1), "Cin mismatch between x and w");
    TORCH_CHECK(W >= kW && H >= kH && D >= kD, "Kernel larger than input");
    int64_t Wo = W - kW + 1;
    int64_t Ho = H - kH + 1;
    int64_t Do = D - kD + 1;

    at::Tensor y = at::empty({B, Cout, Wo, Ho, Do}, x.options());
